using MassageShop.API.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace MassageShop.API.Controllers { [ApiController][Route("api/work-history")][Authorize(Roles="ADMIN")] public class WorkHistoryController:ControllerBase { readonly AppDbContext db; public WorkHistoryController(AppDbContext d)=>db=d; [HttpGet] public async Task<IActionResult> Get([FromQuery]int? employeeId,[FromQuery]DateTime? from,[FromQuery]DateTime? to,[FromQuery]string? type,[FromQuery]string? status){var appts=await db.Appointments.Include(x=>x.Employee).ThenInclude(x=>x!.User).Include(x=>x.Customer).ThenInclude(x=>x.User).Include(x=>x.Service).Where(x=>x.EmployeeId!=null&&(!employeeId.HasValue||x.EmployeeId==employeeId)&&(!from.HasValue||x.AppointmentDate>=from)&&(!to.HasValue||x.AppointmentDate<=to)).Select(x=>new{Id="A"+x.Id,EmployeeId=x.EmployeeId,Date=x.AppointmentDate,Employee=x.Employee!.User.FullName,Position=x.Employee.Position,Type="MASSAGE",Start=x.StartTime,End=x.EndTime,Content=x.Service.Name,Customer=x.Customer.User.FullName,Status=x.Status.ToString(),Rating=(int?)null}).ToListAsync();var shifts=await db.WorkShifts.Include(x=>x.Employee).ThenInclude(x=>x.User).Where(x=>(!employeeId.HasValue||x.EmployeeId==employeeId)&&(!from.HasValue||x.WorkDate>=from)&&(!to.HasValue||x.WorkDate<=to)).Select(x=>new{Id="S"+x.Id,EmployeeId=(int?)x.EmployeeId,Date=x.WorkDate,Employee=x.Employee.User.FullName,Position=x.Employee.Position,Type="SHIFT",Start=x.StartTime,End=x.EndTime,Content=x.ShiftType,Customer=(string?)null,Status=x.Status,Rating=(int?)null}).ToListAsync();var rows=appts.Cast<object>().Concat(shifts.Cast<object>());return Ok(rows);} } }
